function main({ case_json }) {
  const raw = String(case_json ?? "").trim();
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");

  if (start < 0 || end <= start) {
    throw new Error("病例结构化提取结果不是可解析的 JSON 对象");
  }

  const data = JSON.parse(raw.slice(start, end + 1));
  const requiredFields = [
    "case_title",
    "disease"
  ];
  const missingFields = requiredFields.filter(
    (field) => !String(data[field] ?? "").trim()
  );

  if (missingFields.length > 0) {
    throw new Error(`缺少生产工作流必需字段: ${missingFields.join(", ")}`);
  }

  function isSafeRemoteImageUrl(value) {
    if (!value) return false;

    try {
      const url = new URL(value);
      const host = url.hostname.toLowerCase();
      const privateIpv4 = /^(10\.|127\.|169\.254\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/;
      const sensitiveQueryName = /(^|_)(token|access_token|api_key|apikey|auth|authorization|credential|signature|sig)($|_)/i;

      if (!/^https?:$/.test(url.protocol)) return false;
      if (url.username || url.password) return false;
      if (host === "localhost" || host.endsWith(".local") || privateIpv4.test(host)) return false;
      if ([...url.searchParams.keys()].some((key) => sensitiveQueryName.test(key))) return false;

      return true;
    } catch {
      return false;
    }
  }

  function parseCaseImageIndex(value) {
    const rawIndex = String(value ?? "").trim();
    if (!rawIndex) {
      return { case_image_index: "", case_intro_images: [] };
    }

    const normalizedLines = [];
    const remoteUrls = [];

    for (const rawLine of rawIndex.split(/\r?\n/)) {
      const line = rawLine.trim();
      if (!line) continue;

      const parts = line.split("|").map((part) => part.trim());
      const imageId = parts[0] || "";
      const sourceUrl = parts[1] || "";
      const timepoint = parts[2] || "";
      const caption = parts.slice(3).join(" | ").trim();

      if (!/^IMG\d+$/.test(imageId)) continue;

      const safeUrl = isSafeRemoteImageUrl(sourceUrl) ? sourceUrl : "";
      normalizedLines.push(`${imageId} | ${safeUrl} | ${timepoint} | ${caption}`);

      if (safeUrl && !remoteUrls.includes(safeUrl)) {
        remoteUrls.push(safeUrl);
      }
    }

    return {
      case_image_index: normalizedLines.join("\n"),
      case_intro_images: remoteUrls
    };
  }

  const imageData = parseCaseImageIndex(data.case_image_index);

  function stableCaseId(title) {
    const s = String(title || "").trim();
    if (!s) return "";
    let h = 5381;
    for (let i = 0; i < s.length; i++) {
      h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
    }
    return "CASE-" + h.toString(16).toUpperCase();
  }

  const production_variables = {
    case_id: data.case_id || stableCaseId(data.case_title),
    case_title: data.case_title || "",
    disease: data.disease || "",
    case_context: data.case_context || "",
    learning_points: data.learning_points_candidate || "",
    question_count: 5,
    question_draft: "",
    difficulty: data.difficulty || "进阶",
    review_feedback: "首次生成，无上一轮审核意见",
    case_mode: data.case_mode || "全程管理",
    case_timeline: data.case_timeline || "",
    biomarkers: data.biomarkers || "",
    decision_points: data.decision_points_candidate || "",
    adverse_events: data.adverse_events || "",
    evidence_notes: data.evidence_notes || "",
    case_image_index: imageData.case_image_index,
    case_intro_images: imageData.case_intro_images
  };

  return {
    production_variables,
    ...production_variables
  };
}

function main({
  agent_reply,
  case_id,
  case_title,
  disease,
  case_context,
  learning_points,
  case_timeline,
  biomarkers,
  decision_points,
  case_image_index,
  difficulty
}) {
  const text = String(agent_reply ?? "").trim();

  if (!text) {
    throw new Error("肿瘤大查房小工具的 AI 回复内容为空");
  }

  const letters = ["A", "B", "C", "D"];

  function cleanText(value) {
    return String(value ?? "")
      .replace(/\s+/g, " ")
      .trim();
  }

  function displayText(value, maxLength) {
    const normalized = cleanText(value);

    return normalized.length > maxLength
      ? `${normalized.slice(0, maxLength).trim()}……`
      : normalized;
  }

  // 日志前面可能混有HTML、变量模板和其他JSON，
  // 只从目标根字段开始识别结果对象。
  function parseObjectAt(start) {
    let depth = 0;
    let inString = false;
    let escaped = false;

    for (let i = start; i < text.length; i++) {
      const ch = text[i];

      if (inString) {
        if (escaped) {
          escaped = false;
        } else if (ch === "\\") {
          escaped = true;
        } else if (ch === '"') {
          inString = false;
        }

        continue;
      }

      if (ch === '"') {
        inString = true;
        continue;
      }

      if (ch === "{") {
        depth++;
      } else if (ch === "}") {
        depth--;

        if (depth === 0) {
          const raw = text.slice(start, i + 1);

          try {
            return {
              start,
              end: i,
              value: JSON.parse(raw)
            };
          } catch (_) {
            return null;
          }
        }
      }
    }

    return null;
  }

  const blocks = [];
  const rootPattern =
    /\{\s*"(?:decision|generation_status)"\s*:/g;

  let match;

  while ((match = rootPattern.exec(text)) !== null) {
    const parsed = parseObjectAt(match.index);

    if (parsed) {
      blocks.push(parsed);
    }
  }

  const candidates = blocks.filter((item) => {
    const value = item.value;

    return (
      value &&
      value.generation_status === "success" &&
      Array.isArray(value.questions) &&
      value.questions.length >= 2 &&
      value.questions.length <= 5
    );
  });

  if (candidates.length === 0) {
    const safeStop = [...blocks]
      .reverse()
      .find((item) =>
        item.value &&
        item.value.generation_status === "insufficient"
      );

    const reportedMissing =
      safeStop &&
      Array.isArray(safeStop.value.missing_information)
        ? safeStop.value.missing_information
            .map(cleanText)
            .filter(Boolean)
        : [];

    const diagnostic = cleanText(text).slice(0, 1000);
    const insufficientData = {
      schema_version: "1.0",
      case_id: cleanText(case_id),
      cancer_type: cleanText(disease),
      generation_status: "insufficient",
      difficulty: cleanText(difficulty || "进阶"),
      question_count: 0,
      questions: [],
      missing_information:
        reportedMissing.length > 0
          ? reportedMissing
          : [
              diagnostic ||
              "主工作流未返回可发布题目；请检查证据不足或修订耗尽信息。"
            ]
    };

    return {
      final_data: insufficientData,
      final_json: JSON.stringify(insufficientData, null, 2),
      case_page_data: {},
      case_page_json: "{}"
    };
  }

  // 嵌套主工作流内部已经执行独立校验和PASS发布门禁；
  // 外层仅解析其最终发布输出，不猜测或重建校验结论。
  const source = candidates[candidates.length - 1].value;

  const diseaseText = cleanText(disease);

  const cancerType = diseaseText.includes("肺")
    ? "肺癌"
    : diseaseText.includes("胃")
      ? "胃癌"
      : diseaseText.includes("食管")
        ? "食管癌"
        : diseaseText.includes("乳腺")
          ? "乳腺癌"
          : diseaseText.includes("结直肠")
            ? "结直肠癌"
            : diseaseText.includes("肝")
              ? "肝癌"
              : diseaseText.includes("胰腺")
                ? "胰腺癌"
                : diseaseText.includes("卵巢")
                  ? "卵巢癌"
                  : diseaseText.includes("前列腺")
                    ? "前列腺癌"
                    : diseaseText;

  const resolvedCaseId = cleanText(
    case_id || source.case_id
  );

  const resolvedDifficulty = cleanText(
    difficulty ||
    source.difficulty ||
    "进阶"
  );

  const questions = source.questions.map(
    (q, index) => {
      const sourceOptions = Array.isArray(q.options)
        ? [...q.options]
        : letters.map(
            (letter) =>
              q.options &&
              q.options[letter]
          );

      if (
        sourceOptions.length !== 4 ||
        sourceOptions.some(
          (item) =>
            typeof item !== "string" ||
            !item.trim()
        )
      ) {
        throw new Error(
          `Q${index + 1} 的 options 不是四项有效文本`
        );
      }

      if (new Set(sourceOptions).size !== 4) {
        throw new Error(
          `Q${index + 1} 的 options 存在重复选项`
        );
      }

      let originalAnswerIndex;

      if (typeof q.answer === "number") {
        originalAnswerIndex = q.answer;
      } else if (
        /^[A-D]$/i.test(
          String(q.answer ?? "")
        )
      ) {
        originalAnswerIndex = letters.indexOf(
          String(q.answer).toUpperCase()
        );
      } else {
        throw new Error(
          `Q${index + 1} 的 answer 无法识别`
        );
      }

      if (
        originalAnswerIndex < 0 ||
        originalAnswerIndex > 3
      ) {
        throw new Error(
          `Q${index + 1} 的 answer 超出四个选项范围`
        );
      }

      const correctAnswerText =
        sourceOptions[originalAnswerIndex];

      if (
        cleanText(q.answer_text) !==
        cleanText(correctAnswerText)
      ) {
        throw new Error(
          `Q${index + 1} 的 answer_text 与正确选项不一致`
        );
      }

      const options = {
        A: sourceOptions[0],
        B: sourceOptions[1],
        C: sourceOptions[2],
        D: sourceOptions[3]
      };

      const answer =
        letters[originalAnswerIndex];

      const question = String(q.question ?? "");

      return {
        id: q.id || `Q${index + 1}`,
        type: q.type,
        phase: q.phase,
        timepoint: q.timepoint,
        question,
        options,
        answer,
        answer_text: correctAnswerText,
        explain: q.explain,
        keyPoint: q.keyPoint,
        guidelineRef: q.guidelineRef
      };
    }
  );

  const actualQuestionCount =
    questions.length;

  const answerDistribution =
    questions.reduce(
      (counts, question) => {
        counts[question.answer] += 1;
        return counts;
      },
      {
        A: 0,
        B: 0,
        C: 0,
        D: 0
      }
    );

  const answerCounts = Object.values(
    answerDistribution
  );

  const usedAnswerLetters =
    answerCounts.filter(
      (count) => count > 0
    ).length;

  // 2、3、4题时答案位置全部不同；
  // 5题时至少覆盖3个字母，任一字母最多出现2次。
  const minimumUsedLetters =
    actualQuestionCount === 5
      ? 3
      : actualQuestionCount;

  const maximumSameLetterCount =
    actualQuestionCount === 5
      ? 2
      : 1;

  if (
    Math.max(...answerCounts) >
      maximumSameLetterCount ||
    usedAnswerLetters <
      minimumUsedLetters
  ) {
    throw new Error(
      `最终答案分布过度集中：当前${actualQuestionCount}题，` +
      `至少覆盖${minimumUsedLetters}个答案字母，` +
      `任一字母最多出现${maximumSameLetterCount}次`
    );
  }

  const finalData = {
    schema_version: "1.0",
    case_id: resolvedCaseId,
    cancer_type:
      source.cancer_type ||
      cancerType,
    generation_status: "success",
    difficulty: resolvedDifficulty,
    question_count:
      actualQuestionCount,
    questions,
    missing_information:
      Array.isArray(
        source.missing_information
      )
        ? source.missing_information
        : []
  };

  function isSafeRemoteUrl(value) {
    const url = String(value ?? "").trim();

    if (!/^https?:\/\//i.test(url)) {
      return false;
    }

    if (
      /^https?:\/\/(?:localhost|127\.|10\.|192\.168\.|169\.254\.|172\.(?:1[6-9]|2\d|3[01])\.)/i.test(
        url
      )
    ) {
      return false;
    }

    return !/[?&](?:token|access_token|api_key|apikey|auth|authorization|credential|signature|sig)=/i.test(
      url
    );
  }

  const MAX_CASE_IMAGES = 6;

  function isGenericImageLabel(value) {
    const label = cleanText(value);

    if (!label) {
      return true;
    }

    return (
      /^(?:图片|图像|配图|image|img)\s*\d*(?:\.(?:png|jpe?g|gif|webp|bmp))?$/i.test(
        label
      ) ||
      /^\d+\.(?:png|jpe?g|gif|webp|bmp)$/i.test(
        label
      ) ||
      /^(?:演示文稿|幻灯片)\s*\d*$/i.test(
        label
      )
    );
  }

  function isObviousNonCaseImage(value) {
    const label = cleanText(value);

    return /(二维码|扫码|公众号|关注|转发|下载|logo|头像|专家介绍|医生介绍|讲者|个人简介|简历|课程|直播|广告|品牌|海报|封面|栏目|责任编辑|排版编辑)/i.test(
      label
    );
  }

  function temporalKey(value) {
    const match = cleanText(value).match(
      /((?:19|20)\d{2})(?:\s*[年.\/-]\s*(\d{1,2}))?(?:\s*[月.\/-]\s*(\d{1,2}))?/
    );

    if (!match) {
      return "";
    }

    const parts = [match[1]];

    if (match[2]) {
      parts.push(
        String(Number(match[2]))
      );
    }

    if (match[3]) {
      parts.push(
        String(Number(match[3]))
      );
    }

    return parts.join("-");
  }

  function findRelatedTimeline(
    timepoint,
    timelineItems
  ) {
    const normalizedTimepoint =
      cleanText(timepoint);

    if (!normalizedTimepoint) {
      return null;
    }

    const exactTextMatch =
      timelineItems.find(
        (item) =>
          cleanText(item.detail).includes(
            normalizedTimepoint
          ) ||
          cleanText(item.date).includes(
            normalizedTimepoint
          )
      );

    if (exactTextMatch) {
      return exactTextMatch;
    }

    const imageTemporalKey =
      temporalKey(normalizedTimepoint);

    if (!imageTemporalKey) {
      return null;
    }

    return (
      timelineItems.find(
        (item) =>
          temporalKey(item.date) ===
            imageTemporalKey ||
          temporalKey(item.detail) ===
            imageTemporalKey
      ) || null
    );
  }

  function parseImageIndex(
    value,
    timelineItems
  ) {
    const records = [];
    const seenIds = new Set();

    for (
      const rawLine of String(
        value ?? ""
      ).split(/\r?\n/)
    ) {
      const parts = rawLine
        .split("|")
        .map(
          (part) => part.trim()
        );

      const id = parts[0] || "";
      const src = parts[1] || "";
      const timepoint = parts[2] || "";
      const originalCaption =
        parts.slice(3).join(" | ").trim();

      if (
        !/^IMG\d+$/.test(id) ||
        seenIds.has(id) ||
        !isSafeRemoteUrl(src)
      ) {
        continue;
      }

      const caption =
        isGenericImageLabel(
          originalCaption
        )
          ? ""
          : cleanText(
              originalCaption
            );

      const usableTimepoint =
        /^(?:无|不详|未详|未提供|解析结果未提供)$/i.test(
          cleanText(timepoint)
        )
          ? ""
          : cleanText(timepoint);

      // 仅按原始图注和时间点筛选；
      // 不读取图片内容，也不根据文件名推断医学含义。
      if (
        (!caption &&
          !usableTimepoint) ||
        isObviousNonCaseImage(
          originalCaption
        )
      ) {
        continue;
      }

      const relatedTimeline =
        findRelatedTimeline(
          usableTimepoint,
          timelineItems
        );

      seenIds.add(id);

      records.push({
        id,
        src,
        timepoint:
          usableTimepoint,
        caption,
        alt:
          caption ||
          `病例原始图片 ${id}`,
        mapping_status:
          relatedTimeline
            ? "matched_by_timepoint"
            : "caption_only",
        related_timeline:
          relatedTimeline
            ? {
                date:
                  relatedTimeline.date,
                title:
                  relatedTimeline.title,
                detail:
                  relatedTimeline.detail
              }
            : null
      });

      if (
        records.length >=
        MAX_CASE_IMAGES
      ) {
        break;
      }
    }

    return records;
  }

  function buildSummaryItems() {
    const candidates = [
      [
        "患者与就诊背景",
        case_context
      ],
      [
        "疾病与分期",
        disease
      ],
      [
        "分子与病理",
        biomarkers
      ],
      [
        "核心教学点",
        learning_points ||
          decision_points
      ]
    ];

    return candidates
      .filter(
        ([, value]) =>
          cleanText(value)
      )
      .map(
        (
          [label, value],
          index
        ) => ({
          order: index + 1,
          label,
          value: displayText(
            value,
            260
          )
        })
      );
  }

  function buildTimelineItems() {
    const rawTimeline =
      String(
        case_timeline ?? ""
      ).trim();

    if (!rawTimeline) {
      return [];
    }

    let entries = rawTimeline
      .split(/\r?\n|[；;]/)
      .map(
        (item) => item.trim()
      )
      .filter(Boolean);

    if (entries.length === 0) {
      entries = [rawTimeline];
    }

    return entries.map(
      (detail, index) => {
        const dateMatch =
          detail.match(
            /(?:19|20)\d{2}(?:(?:年\s*\d{1,2}月?(?:\s*\d{1,2}日?)?)|(?:[.\/-]\s*\d{1,2}(?:[.\/-]\s*\d{1,2})?))?\+?/
          );

        return {
          date: dateMatch
            ? cleanText(
                dateMatch[0]
              )
            : "时间未详",
          title:
            `诊疗节点 ${index + 1}`,
          detail: displayText(
            detail,
            300
          )
        };
      }
    );
  }

  const timelineItems =
    buildTimelineItems();

  const pageImages =
    parseImageIndex(
      case_image_index,
      timelineItems
    );

  const heroImage =
    pageImages.find(
      (item) =>
        item.related_timeline
    ) ||
    pageImages.find(
      (item) => item.caption
    ) ||
    null;

  const resolvedTitle =
    cleanText(
      case_title ||
      source.case_title ||
      diseaseText ||
      "肿瘤病例"
    );

  const overviewTabs = [
    {
      id: "summary",
      label: "病例摘要",
      order: 1,
      summary_items:
        buildSummaryItems()
    },
    {
      id: "timeline",
      label: "病程轴",
      order: 2,
      timeline_items:
        timelineItems
    }
  ];

  if (pageImages.length > 0) {
    overviewTabs.push({
      id: "images",
      label: "病例图片",
      order: 3,

      // 图片只出现在病例详情页；
      // 不输出题号、答案或医学图像推断。
      image_items:
        pageImages
    });
  }

  const casePageData = {
    schema_version: "1.0",
    case_id: resolvedCaseId,
    cancer_type:
      source.cancer_type ||
      cancerType,
    difficulty:
      resolvedDifficulty,

    // 与最终实际发布题量保持一致。
    decision_point_count:
      actualQuestionCount,

    image: {
      src: heroImage
        ? heroImage.src
        : "",
      alt: heroImage
        ? (
            heroImage.caption ||
            `${resolvedTitle}病例主题图`
          )
        : ""
    },

    home: {
      recommendation_label:
        "今日推荐病例",
      display_title:
        resolvedTitle,
      description:
        displayText(
          case_context ||
          diseaseText,
          180
        )
    },

    overview: {
      hero: {
        title:
          resolvedTitle,
        subtitle:
          displayText(
            learning_points ||
            diseaseText,
            120
          )
      },
      tabs:
        overviewTabs
    }
  };

  return {
    final_data: finalData,
    final_json:
      JSON.stringify(
        finalData,
        null,
        2
      ),
    case_page_data:
      casePageData,
    case_page_json:
      JSON.stringify(
        casePageData,
        null,
        2
      )
  };
}

function main({ raw_json }) {
  const input = String(raw_json ?? "").trim();

  if (!input) {
    throw new Error("病例结构化提取结果为空");
  }

  /**
   * 删除模型可能输出的 Markdown 代码围栏。
   */
  function removeCodeFence(value) {
    return String(value ?? "")
      .replace(/^\s*```(?:json)?\s*/i, "")
      .replace(/\s*```\s*$/i, "")
      .trim();
  }

  /**
   * 截取第一个 JSON 根对象。
   */
  function extractJsonObject(value) {
    const source = removeCodeFence(value);
    const start = source.indexOf("{");
    const end = source.lastIndexOf("}");

    if (start < 0 || end <= start) {
      throw new Error("未找到可解析的 JSON 根对象");
    }

    return source.slice(start, end + 1);
  }

  /**
   * 修复 JSON 字符串内部未转义的半角双引号，
   * 同时处理字符串内部的真实换行和制表符。
   */
  function repairUnescapedQuotes(value) {
    let result = "";
    let inString = false;
    let escaped = false;

    for (let index = 0; index < value.length; index++) {
      const char = value[index];

      if (!inString) {
        result += char;

        if (char === '"') {
          inString = true;
          escaped = false;
        }

        continue;
      }

      if (escaped) {
        result += char;
        escaped = false;
        continue;
      }

      if (char === "\\") {
        result += char;
        escaped = true;
        continue;
      }

      if (char === "\r") {
        if (value[index + 1] === "\n") {
          index += 1;
        }

        result += "\\n";
        continue;
      }

      if (char === "\n") {
        result += "\\n";
        continue;
      }

      if (char === "\t") {
        result += "\\t";
        continue;
      }

      if (char !== '"') {
        result += char;
        continue;
      }

      // 判断当前双引号是字符串结束符，还是正文内部未转义引号。
      let nextIndex = index + 1;

      while (
        nextIndex < value.length &&
        /\s/.test(value[nextIndex])
      ) {
        nextIndex += 1;
      }

      const nextChar =
        nextIndex < value.length ? value[nextIndex] : "";

      const isClosingQuote =
        nextChar === ":" ||
        nextChar === "," ||
        nextChar === "}" ||
        nextChar === "]" ||
        nextChar === "";

      if (isClosingQuote) {
        result += '"';
        inString = false;
      } else {
        result += '\\"';
      }
    }

    if (inString) {
      throw new Error("JSON 字符串引号未闭合，无法安全修复");
    }

    return result;
  }

  /**
   * 删除对象或数组末尾多余的逗号。
   */
  function removeTrailingCommas(value) {
    let result = "";
    let inString = false;
    let escaped = false;

    for (let index = 0; index < value.length; index++) {
      const char = value[index];

      if (inString) {
        result += char;

        if (escaped) {
          escaped = false;
        } else if (char === "\\") {
          escaped = true;
        } else if (char === '"') {
          inString = false;
        }

        continue;
      }

      if (char === '"') {
        inString = true;
        result += char;
        continue;
      }

      if (char === ",") {
        let nextIndex = index + 1;

        while (
          nextIndex < value.length &&
          /\s/.test(value[nextIndex])
        ) {
          nextIndex += 1;
        }

        const nextChar =
          nextIndex < value.length ? value[nextIndex] : "";

        if (nextChar === "}" || nextChar === "]") {
          continue;
        }
      }

      result += char;
    }

    return result;
  }

  /**
   * 解析原始 JSON；失败时依次进行受控修复。
   */
  const source = extractJsonObject(input);
  let parsed;

  try {
    parsed = JSON.parse(source);
  } catch (firstError) {
    const quoteRepaired = repairUnescapedQuotes(source);
    const fullyRepaired = removeTrailingCommas(quoteRepaired);

    try {
      parsed = JSON.parse(fullyRepaired);
    } catch (secondError) {
      throw new Error(
        `病例结构化 JSON 修复失败：${secondError.message}`
      );
    }
  }

  if (
    !parsed ||
    typeof parsed !== "object" ||
    Array.isArray(parsed)
  ) {
    throw new Error("病例结构化结果必须是单个 JSON 对象");
  }

  /**
   * evidence_notes 只能保留患者正文内部的不确定信息，
   * 禁止记录导语、专家观点与正文的比较。
   */
  if (typeof parsed.evidence_notes === "string") {
    parsed.evidence_notes = parsed.evidence_notes
      .split(/\r?\n/)
      .map((line) => line.trim())
      .filter(Boolean)
      .filter((line) => {
        const secondarySourceLeak =
          /(文章导语|导语|专家观点|专家点评|编辑总结|二次资料|以正文为准|不同部分表述)/i;

        const prSdComparison =
          /(?:正文|患者病例).*(?:PR|SD).*(?:导语|专家)|(?:导语|专家).*(?:PR|SD).*(?:正文|患者病例)/i;

        return (
          !secondarySourceLeak.test(line) &&
          !prSdComparison.test(line)
        );
      })
      .join("\n");
  }

  /**
   * patient_facts 只能保存具体患者事实，
   * 删除参考文献、图片推断等分类标签。
   */
  if (Array.isArray(parsed.patient_facts)) {
    parsed.patient_facts = parsed.patient_facts
      .map((item) => String(item ?? "").trim())
      .filter(Boolean)
      .filter((item) => {
        return !/^(参考文献|参考文献列表|图片推断|文章导语与二次资料|专家观点|专家点评|已移除内容类别)(?:[：:].*)?$/i.test(
          item
        );
      });
  }

  /**
   * missing_information 不能把已移除内容类别当作病例缺失信息。
   */
  if (Array.isArray(parsed.missing_information)) {
    parsed.missing_information =
      parsed.missing_information
        .map((item) => String(item ?? "").trim())
        .filter(Boolean)
        .filter((item) => {
          return !/^(参考文献|参考文献列表|图片推断|文章导语与二次资料|专家观点|专家点评|已移除内容类别)(?:[：:].*)?$/i.test(
            item
          );
        });
  }

  /**
   * 禁止保留模型自行计算出来的日期。
   * 保留原文的持续时间事实，但将日期改为“时间不详”。
   */
  if (typeof parsed.case_timeline === "string") {
    parsed.case_timeline = parsed.case_timeline
      .split(/\r?\n/)
      .map((line) => {
        const trimmed = line.trim();

        if (!trimmed) {
          return "";
        }

        if (/（?推算）?/i.test(trimmed)) {
          const separatorIndex = trimmed.indexOf("：");

          if (separatorIndex >= 0) {
            const fact = trimmed
              .slice(separatorIndex + 1)
              .replace(/（?推算）?/gi, "")
              .trim();

            return fact ? `时间不详：${fact}` : "";
          }

          return trimmed
            .replace(/（?推算）?/gi, "")
            .replace(
              /^\d{4}\s*年(?:\s*\d{1,2}\s*月)?/,
              "时间不详"
            )
            .trim();
        }

        return trimmed;
      })
      .filter(Boolean)
      .join("\n");
  }

  return {
    repaired_json: JSON.stringify(parsed),
    repaired_data: parsed
  };
}

